import com.example.starter.cems.web.dto.RegisterRequest;

/**
 * H2（MODE=MySQL）真实事务/并发边界测试：
 * 限排令插入失败时基数冻结随事务回滚；并发下达仅一个受理；并发同 requestId 唯一受理。
