        assertEquals(threads - 1, rejected.get(), "其余被唯一约束拒绝");
        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM restriction_order WHERE outfall_code = 'OUT-CONC'",
                Integer.class), "仅一个限排令");
        assertEquals(1, jdbc.queryForObject(
